import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as a}from"./app-Dc59EzjI.js";var o=JSON.parse(`{"path":"/Linux/01_Linux%E5%9F%BA%E7%A1%80/04_%E7%BD%91%E7%BB%9C%E9%85%8D%E7%BD%AE%E4%B8%8E%E9%98%B2%E7%81%AB%E5%A2%99.html","title":"网络配置与防火墙","lang":"zh-CN","frontmatter":{"title":"网络配置与防火墙","icon":"fas fa-network-wired","order":4,"category":["Linux基础"],"tag":["Linux","网络配置","防火墙","iptables","firewalld","SSH","网络诊断"]},"git":{"createdTime":1780623253000,"updatedTime":1780623253000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":21.6,"words":6481},"filePathRelative":"Linux/01_Linux基础/04_网络配置与防火墙.md"}`),s={name:`04_网络配置与防火墙.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="网络配置与防火墙" tabindex="-1"><a class="header-anchor" href="#网络配置与防火墙"><span>网络配置与防火墙</span></a></h1><p>网络是 Linux 服务器生命的血液——无论是提供 Web 服务、数据库访问，还是集群通信，一切皆依赖网络的正确配置与安全防护。本文从网络接口管理讲起，深入 DNS 解析机制，再逐层剖析 iptables 四表五链与 firewalld 的设计哲学，最后覆盖网络诊断与 SSH 安全加固，帮你构建一张&quot;通得了、管得住、查得出&quot;的企业级网络知识网。</p><h2 id="_1-网络接口管理" tabindex="-1"><a class="header-anchor" href="#_1-网络接口管理"><span>1. 网络接口管理</span></a></h2><h3 id="_1-1-网络接口的概念" tabindex="-1"><a class="header-anchor" href="#_1-1-网络接口的概念"><span>1.1 网络接口的概念</span></a></h3><p>网络接口（Network Interface）是操作系统与网络硬件之间的抽象层。每个接口拥有唯一的名称和配置参数：</p><table><thead><tr><th>接口类型</th><th>命名规则</th><th>说明</th></tr></thead><tbody><tr><td>物理网卡</td><td><code>eth0</code>、<code>enp3s0</code></td><td>以太网接口</td></tr><tr><td>无线网卡</td><td><code>wlan0</code>、<code>wlp2s0</code></td><td>Wi-Fi 接口</td></tr><tr><td>回环接口</td><td><code>lo</code></td><td>本地回环 127.0.0.1</td></tr><tr><td>虚拟网桥</td><td><code>br0</code>、<code>virbr0</code></td><td>桥接接口</td></tr><tr><td>VLAN</td><td><code>eth0.100</code>、<code>enp3s0.100</code></td><td>802.1Q VLAN 子接口</td></tr><tr><td>Bond</td><td><code>bond0</code></td><td>网卡绑定接口</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">可预测命名规则</p><p>CentOS 7+ / Ubuntu 16.04+ 采用 systemd 的可预测网络接口命名：</p><ul><li><code>en</code> = 以太网，<code>wl</code> = 无线，<code>ww</code> = WWAN</li><li><code>p3s0</code> = PCI 插槽位置，<code>o1</code> = 板载网卡序号</li><li>例如 <code>enp3s0</code> = PCI 插槽 3 上的以太网卡</li></ul></div><h3 id="_1-2-ip-命令家族" tabindex="-1"><a class="header-anchor" href="#_1-2-ip-命令家族"><span>1.2 ip 命令家族</span></a></h3><p><code>ip</code> 命令来自 <code>iproute2</code> 工具包，是 <code>ifconfig</code>/<code>route</code>/<code>netstat</code> 的现代替代品：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有网络接口</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> show</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看指定接口</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> show</span><span style="color:#98C379;"> enp3s0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 启用/禁用接口</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> set</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> up</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> set</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> down</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 修改接口 MTU</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> set</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> mtu</span><span style="color:#D19A66;"> 9000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 修改接口 MAC 地址（需先 down）</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> set</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> down</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> set</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> address</span><span style="color:#98C379;"> 00:11:22:33:44:55</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> link</span><span style="color:#98C379;"> set</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> up</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>IP 地址管理：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有 IP 地址</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> addr</span><span style="color:#98C379;"> show</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> a</span><span style="color:#7F848E;font-style:italic;">    # 简写</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加 IP 地址</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> addr</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> 192.168.1.100/24</span><span style="color:#98C379;"> dev</span><span style="color:#98C379;"> enp3s0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加辅助 IP（同一接口多 IP）</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> addr</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> 192.168.1.101/24</span><span style="color:#98C379;"> dev</span><span style="color:#98C379;"> enp3s0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除 IP 地址</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> addr</span><span style="color:#98C379;"> del</span><span style="color:#98C379;"> 192.168.1.100/24</span><span style="color:#98C379;"> dev</span><span style="color:#98C379;"> enp3s0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 清空接口所有 IP</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> addr</span><span style="color:#98C379;"> flush</span><span style="color:#98C379;"> dev</span><span style="color:#98C379;"> enp3s0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>路由管理：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看路由表</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#98C379;"> show</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#7F848E;font-style:italic;">    # 简写</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加默认网关</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> default</span><span style="color:#98C379;"> via</span><span style="color:#D19A66;"> 192.168.1.1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加静态路由</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> 10.0.0.0/8</span><span style="color:#98C379;"> via</span><span style="color:#D19A66;"> 192.168.1.254</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加路由指定出接口</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> 172.16.0.0/16</span><span style="color:#98C379;"> dev</span><span style="color:#98C379;"> enp3s0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除路由</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#98C379;"> del</span><span style="color:#98C379;"> 10.0.0.0/8</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 修改路由（replace）</span></span>
<span class="line"><span style="color:#61AFEF;">ip</span><span style="color:#98C379;"> route</span><span style="color:#98C379;"> replace</span><span style="color:#98C379;"> default</span><span style="color:#98C379;"> via</span><span style="color:#D19A66;"> 192.168.1.2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">ip 命令的记忆技巧</p><p><code>ip</code> 命令遵循统一的语法结构：<code>ip &lt;对象&gt; &lt;操作&gt; &lt;参数&gt;</code></p><ul><li>对象：<code>link</code>（链路层）、<code>addr</code>（网络层）、<code>route</code>（路由）、<code>neigh</code>（ARP/邻居）</li><li>操作：<code>show</code>（查看）、<code>add</code>（添加）、<code>del</code>（删除）、<code>set</code>（修改）、<code>flush</code>（清空）</li></ul></div><h3 id="_1-3-nmcli-networkmanager-命令行" tabindex="-1"><a class="header-anchor" href="#_1-3-nmcli-networkmanager-命令行"><span>1.3 nmcli（NetworkManager 命令行）</span></a></h3><p>NetworkManager 是桌面和部分服务器发行版的网络管理守护进程，<code>nmcli</code> 是其命令行接口：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有连接</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> show</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看设备状态</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> device</span><span style="color:#98C379;"> status</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 创建以太网静态 IP 连接</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> con-name</span><span style="color:#98C379;"> static-eth0</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#98C379;">  type</span><span style="color:#98C379;"> ethernet</span><span style="color:#98C379;"> ifname</span><span style="color:#98C379;"> enp3s0</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#98C379;">  ip4</span><span style="color:#98C379;"> 192.168.1.100/24</span><span style="color:#98C379;"> gw4</span><span style="color:#D19A66;"> 192.168.1.1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 设置 DNS</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> modify</span><span style="color:#98C379;"> static-eth0</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#98C379;">  ipv4.dns</span><span style="color:#98C379;"> &quot;8.8.8.8 8.8.4.4&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 创建 DHCP 连接</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> con-name</span><span style="color:#98C379;"> dhcp-eth0</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#98C379;">  type</span><span style="color:#98C379;"> ethernet</span><span style="color:#98C379;"> ifname</span><span style="color:#98C379;"> enp3s0</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#98C379;">  ipv4.method</span><span style="color:#98C379;"> auto</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 启用/禁用连接</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> up</span><span style="color:#98C379;"> static-eth0</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> down</span><span style="color:#98C379;"> static-eth0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 修改连接参数</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> modify</span><span style="color:#98C379;"> static-eth0</span><span style="color:#98C379;"> ipv4.addresses</span><span style="color:#98C379;"> &quot;192.168.1.200/24&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看连接详情</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> show</span><span style="color:#98C379;"> static-eth0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>nmcli 交互式编辑器：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 进入交互式编辑模式</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> edit</span><span style="color:#98C379;"> con-name</span><span style="color:#98C379;"> static-eth0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在交互模式中</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#98C379;">set</span><span style="color:#98C379;"> ipv4.addresses</span><span style="color:#98C379;"> 192.168.1.200/24</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#98C379;">set</span><span style="color:#98C379;"> ipv4.gateway</span><span style="color:#D19A66;"> 192.168.1.1</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#98C379;">set</span><span style="color:#98C379;"> ipv4.dns</span><span style="color:#D19A66;"> 8.8.8.8</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#98C379;">save</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#ABB2BF;">&gt; </span><span style="color:#98C379;">quit</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-4-netplan-ubuntu-18-04" tabindex="-1"><a class="header-anchor" href="#_1-4-netplan-ubuntu-18-04"><span>1.4 netplan（Ubuntu 18.04+）</span></a></h3><p>Ubuntu 从 18.04 LTS 开始使用 netplan 作为网络配置后端，通过 YAML 文件描述网络：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/netplan/01-netcfg.yaml</span></span>
<span class="line"><span style="color:#E06C75;">network</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  version</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">2</span></span>
<span class="line"><span style="color:#E06C75;">  renderer</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">networkd</span><span style="color:#7F848E;font-style:italic;">    # 或 NetworkManager</span></span>
<span class="line"><span style="color:#E06C75;">  ethernets</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    enp3s0</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      dhcp4</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">no</span></span>
<span class="line"><span style="color:#E06C75;">      addresses</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">        - </span><span style="color:#98C379;">192.168.1.100/24</span></span>
<span class="line"><span style="color:#E06C75;">      gateway4</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">192.168.1.1</span></span>
<span class="line"><span style="color:#E06C75;">      nameservers</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        addresses</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">          - </span><span style="color:#D19A66;">8.8.8.8</span></span>
<span class="line"><span style="color:#ABB2BF;">          - </span><span style="color:#D19A66;">8.8.4.4</span></span>
<span class="line"><span style="color:#E06C75;">        search</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">          - </span><span style="color:#98C379;">example.com</span></span>
<span class="line"><span style="color:#E06C75;">      mtu</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">1500</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Bonding 配置示例：</strong></p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/netplan/02-bond.yaml</span></span>
<span class="line"><span style="color:#E06C75;">network</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">  version</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">2</span></span>
<span class="line"><span style="color:#E06C75;">  renderer</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">networkd</span></span>
<span class="line"><span style="color:#E06C75;">  bonds</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    bond0</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">      interfaces</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">        - </span><span style="color:#98C379;">enp3s0</span></span>
<span class="line"><span style="color:#ABB2BF;">        - </span><span style="color:#98C379;">enp4s0</span></span>
<span class="line"><span style="color:#E06C75;">      parameters</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">        mode</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">active-backup</span></span>
<span class="line"><span style="color:#E06C75;">        mii-monitor-interval</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">100</span></span>
<span class="line"><span style="color:#E06C75;">      addresses</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">        - </span><span style="color:#98C379;">192.168.1.100/24</span></span>
<span class="line"><span style="color:#E06C75;">      gateway4</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">192.168.1.1</span></span>
<span class="line"><span style="color:#E06C75;">  ethernets</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#E06C75;">    enp3s0</span><span style="color:#ABB2BF;">: {}</span></span>
<span class="line"><span style="color:#E06C75;">    enp4s0</span><span style="color:#ABB2BF;">: {}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 验证并应用配置</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> netplan</span><span style="color:#98C379;"> try</span><span style="color:#7F848E;font-style:italic;">     # 先测试，不生效可自动回滚</span></span>
<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> netplan</span><span style="color:#98C379;"> apply</span><span style="color:#7F848E;font-style:italic;">   # 直接应用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">netplan 缩进陷阱</p><p>YAML 对缩进极其敏感！使用空格而非 Tab，每层缩进 2 个空格。<code>netplan try</code> 会先验证配置合法性，避免因配置错误导致网络断开——生产环境务必使用 <code>try</code> 而非直接 <code>apply</code>。</p></div><h3 id="_1-5-传统配置文件-centos-rhel" tabindex="-1"><a class="header-anchor" href="#_1-5-传统配置文件-centos-rhel"><span>1.5 传统配置文件（CentOS/RHEL）</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/sysconfig/network-scripts/ifcfg-enp3s0</span></span>
<span class="line"><span style="color:#E06C75;">TYPE</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">Ethernet</span></span>
<span class="line"><span style="color:#E06C75;">BOOTPROTO</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">static</span></span>
<span class="line"><span style="color:#E06C75;">NAME</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">enp3s0</span></span>
<span class="line"><span style="color:#E06C75;">DEVICE</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">enp3s0</span></span>
<span class="line"><span style="color:#E06C75;">ONBOOT</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">yes</span></span>
<span class="line"><span style="color:#E06C75;">IPADDR</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">192.168.1.100</span></span>
<span class="line"><span style="color:#E06C75;">PREFIX</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">24</span></span>
<span class="line"><span style="color:#E06C75;">GATEWAY</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">192.168.1.1</span></span>
<span class="line"><span style="color:#E06C75;">DNS1</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">8.8.8.8</span></span>
<span class="line"><span style="color:#E06C75;">DNS2</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">8.8.4.4</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 重启网络服务</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> restart</span><span style="color:#98C379;"> network</span><span style="color:#7F848E;font-style:italic;">    # CentOS 6/7</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> reload</span><span style="color:#7F848E;font-style:italic;">      # CentOS 8+/使用 NetworkManager</span></span>
<span class="line"><span style="color:#61AFEF;">nmcli</span><span style="color:#98C379;"> connection</span><span style="color:#98C379;"> up</span><span style="color:#98C379;"> enp3s0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-dns-解析" tabindex="-1"><a class="header-anchor" href="#_2-dns-解析"><span>2. DNS 解析</span></a></h2><h3 id="_2-1-dns-解析流程" tabindex="-1"><a class="header-anchor" href="#_2-1-dns-解析流程"><span>2.1 DNS 解析流程</span></a></h3>`,32),i(d,{code:``}),o[1]||=n(`<h3 id="_2-2-etc-resolv-conf" tabindex="-1"><a class="header-anchor" href="#_2-2-etc-resolv-conf"><span>2.2 /etc/resolv.conf</span></a></h3><p>这是传统 DNS 配置文件，被 glibc 解析器直接读取：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/resolv.conf</span></span>
<span class="line"><span style="color:#61AFEF;">nameserver</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">          # 主 DNS</span></span>
<span class="line"><span style="color:#61AFEF;">nameserver</span><span style="color:#D19A66;"> 8.8.4.4</span><span style="color:#7F848E;font-style:italic;">          # 备 DNS</span></span>
<span class="line"><span style="color:#61AFEF;">search</span><span style="color:#98C379;"> example.com</span><span style="color:#98C379;"> corp.local</span><span style="color:#7F848E;font-style:italic;">  # 搜索域</span></span>
<span class="line"><span style="color:#61AFEF;">options</span><span style="color:#98C379;"> timeout:2</span><span style="color:#98C379;"> attempts:3</span><span style="color:#7F848E;font-style:italic;">   # 超时和重试</span></span>
<span class="line"><span style="color:#61AFEF;">options</span><span style="color:#98C379;"> ndots:5</span><span style="color:#7F848E;font-style:italic;">                # 点数阈值</span></span>
<span class="line"><span style="color:#61AFEF;">options</span><span style="color:#98C379;"> single-request-reopen</span><span style="color:#7F848E;font-style:italic;">  # 解决 IPv4/IPv6 竞态</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>参数</th><th>含义</th><th>默认值</th></tr></thead><tbody><tr><td><code>nameserver</code></td><td>DNS 服务器地址，最多 3 个</td><td>-</td></tr><tr><td><code>search</code></td><td>短域名自动补全的搜索域</td><td>本地域</td></tr><tr><td><code>options timeout</code></td><td>单次查询超时秒数</td><td>5</td></tr><tr><td><code>options attempts</code></td><td>每个服务器重试次数</td><td>2</td></tr><tr><td><code>options ndots</code></td><td>名字中点数少于此值则先追加搜索域</td><td>1</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">resolv.conf 被覆盖问题</p><p>如果系统运行 NetworkManager 或 systemd-resolved，它们会自动生成 <code>/etc/resolv.conf</code>，手动修改会被覆盖。解决方案：</p><ul><li><strong>NetworkManager</strong>：<code>nmcli con modify &lt;name&gt; ipv4.dns &quot;8.8.8.8&quot;</code></li><li><strong>systemd-resolved</strong>：修改 <code>/etc/systemd/resolved.conf</code></li><li><strong>防覆盖</strong>：<code>chattr +i /etc/resolv.conf</code>（不推荐，治标不治本）</li></ul></div><h3 id="_2-3-systemd-resolved" tabindex="-1"><a class="header-anchor" href="#_2-3-systemd-resolved"><span>2.3 systemd-resolved</span></a></h3><p>现代 Linux 发行版（Ubuntu 16.10+、CentOS 8+）使用 systemd-resolved 提供本地 DNS 缓存：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看状态</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> status</span><span style="color:#98C379;"> systemd-resolved</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 配置文件 /etc/systemd/resolved.conf</span></span>
<span class="line"><span style="color:#ABB2BF;">[Resolve]</span></span>
<span class="line"><span style="color:#E06C75;">DNS</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">8.8.8.8</span><span style="color:#61AFEF;"> 8.8.4.4</span></span>
<span class="line"><span style="color:#E06C75;">FallbackDNS</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">1.1.1.1</span><span style="color:#61AFEF;"> 1.0.0.1</span></span>
<span class="line"><span style="color:#E06C75;">Domains</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">~example.com</span></span>
<span class="line"><span style="color:#E06C75;">LLMNR</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">no</span></span>
<span class="line"><span style="color:#E06C75;">DNSOverTLS</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">opportunistic</span></span>
<span class="line"><span style="color:#E06C75;">Cache</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">yes</span></span>
<span class="line"><span style="color:#E06C75;">CacheFromLocalhost</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">yes</span></span>
<span class="line"><span style="color:#E06C75;">DNSStubListener</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">yes</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 resolvectl 管理和查询</span></span>
<span class="line"><span style="color:#61AFEF;">resolvectl</span><span style="color:#98C379;"> status</span><span style="color:#7F848E;font-style:italic;">                    # 查看全局和每个接口的 DNS 状态</span></span>
<span class="line"><span style="color:#61AFEF;">resolvectl</span><span style="color:#98C379;"> query</span><span style="color:#98C379;"> www.example.com</span><span style="color:#7F848E;font-style:italic;">     # 解析域名</span></span>
<span class="line"><span style="color:#61AFEF;">resolvectl</span><span style="color:#98C379;"> domain</span><span style="color:#98C379;"> enp3s0</span><span style="color:#98C379;"> ~corp.local</span><span style="color:#7F848E;font-style:italic;"> # 设置接口路由域</span></span>
<span class="line"><span style="color:#61AFEF;">resolvectl</span><span style="color:#98C379;"> dns</span><span style="color:#98C379;"> enp3s0</span><span style="color:#D19A66;"> 10.0.0.1</span><span style="color:#7F848E;font-style:italic;">       # 设置接口 DNS</span></span>
<span class="line"><span style="color:#61AFEF;">resolvectl</span><span style="color:#98C379;"> flush-caches</span><span style="color:#7F848E;font-style:italic;">              # 清除缓存</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">DNSOverTLS 配置</p><p><code>DNSOverTLS=opportunistic</code> 表示尝试使用 TLS 查询，失败则回退明文；<code>DNSOverTLS=yes</code> 则强制 TLS，无法连接时查询失败。适合安全要求高的环境。</p></div><h3 id="_2-4-etc-nsswitch-conf" tabindex="-1"><a class="header-anchor" href="#_2-4-etc-nsswitch-conf"><span>2.4 /etc/nsswitch.conf</span></a></h3><p>Name Service Switch 决定了名称解析的查找顺序：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/nsswitch.conf 关键行</span></span>
<span class="line"><span style="color:#61AFEF;">hosts:</span><span style="color:#98C379;">      files</span><span style="color:#98C379;"> resolve</span><span style="color:#ABB2BF;"> [!UNAVAIL=return] dns myhostname</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 解读：先查 files(/etc/hosts)，再查 resolve(systemd-resolved)，</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#       如果 resolve 可用就返回结果，否则查 dns，最后查 myhostname</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-防火墙基础——iptables" tabindex="-1"><a class="header-anchor" href="#_3-防火墙基础——iptables"><span>3. 防火墙基础——iptables</span></a></h2><h3 id="_3-1-iptables-架构-四表五链" tabindex="-1"><a class="header-anchor" href="#_3-1-iptables-架构-四表五链"><span>3.1 iptables 架构：四表五链</span></a></h3><p>iptables 是 Linux 内核 Netfilter 框架的用户态工具，通过&quot;表-链-规则&quot;三级结构组织数据包处理逻辑：</p>`,16),i(d,{code:``}),o[2]||=n(`<p><strong>四表职责：</strong></p><table><thead><tr><th>表</th><th>优先级</th><th>用途</th><th>可用链</th></tr></thead><tbody><tr><td><code>raw</code></td><td>最高</td><td>决定数据包是否被连接追踪</td><td>PREROUTING, OUTPUT</td></tr><tr><td><code>mangle</code></td><td>高</td><td>修改 TTL/TOS/MARK 等包头字段</td><td>全部五链</td></tr><tr><td><code>nat</code></td><td>中</td><td>源/目标地址转换（SNAT/DNAT）</td><td>PREROUTING, OUTPUT, POSTROUTING</td></tr><tr><td><code>filter</code></td><td>最低</td><td>数据包过滤（ACCEPT/DROP/REJECT）</td><td>INPUT, FORWARD, OUTPUT</td></tr></tbody></table><h3 id="_3-2-数据包在-iptables-中的流转" tabindex="-1"><a class="header-anchor" href="#_3-2-数据包在-iptables-中的流转"><span>3.2 数据包在 iptables 中的流转</span></a></h3>`,3),i(d,{code:``}),o[3]||=n(`<div class="hint-container important"><p class="hint-container-title">规则匹配顺序</p><p>iptables 规则从上到下依次匹配，<strong>第一条匹配的规则决定数据包命运</strong>，后续规则不再检查。这意味着：</p><ol><li>规则顺序至关重要</li><li>更具体的规则应放在更前面</li><li>最后一条通常是默认策略（ACCEPT 或 DROP）</li></ol></div><h3 id="_3-3-iptables-基本操作" tabindex="-1"><a class="header-anchor" href="#_3-3-iptables-基本操作"><span>3.3 iptables 基本操作</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有规则（带行号和计数器）</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -L</span><span style="color:#D19A66;"> -n</span><span style="color:#D19A66;"> -v</span><span style="color:#D19A66;"> --line-numbers</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 filter 表 INPUT 链</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> filter</span><span style="color:#D19A66;"> -L</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -n</span><span style="color:#D19A66;"> -v</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 nat 表</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -L</span><span style="color:#D19A66;"> -n</span><span style="color:#D19A66;"> -v</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看规则计数器归零</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -Z</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>添加规则：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 允许已建立的和相关的连接（第一条规则，最重要！）</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -m</span><span style="color:#98C379;"> conntrack</span><span style="color:#D19A66;"> --ctstate</span><span style="color:#98C379;"> ESTABLISHED,RELATED</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许回环接口</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> lo</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许 SSH</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 22</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许 HTTP/HTTPS</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 80</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 443</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许特定网段</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> 10.0.0.0/8</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许 ICMP（ping）</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> icmp</span><span style="color:#D19A66;"> --icmp-type</span><span style="color:#98C379;"> echo-request</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 插入规则到指定位置</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -I</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> 2</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 8080</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 默认策略</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -P</span><span style="color:#98C379;"> INPUT</span><span style="color:#98C379;"> DROP</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -P</span><span style="color:#98C379;"> FORWARD</span><span style="color:#98C379;"> DROP</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -P</span><span style="color:#98C379;"> OUTPUT</span><span style="color:#98C379;"> ACCEPT</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>删除规则：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 按行号删除</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -D</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> 3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 按规则内容删除</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -D</span><span style="color:#98C379;"> INPUT</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 22</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 清空所有规则</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -F</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 清空特定链</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -F</span><span style="color:#98C379;"> INPUT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除自定义链</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -X</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-常用匹配条件" tabindex="-1"><a class="header-anchor" href="#_3-4-常用匹配条件"><span>3.4 常用匹配条件</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 协议匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-p</span><span style="color:#98C379;"> tcp</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> udp</span><span style="color:#98C379;"> /</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> icmp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 端口匹配</span></span>
<span class="line"><span style="color:#61AFEF;">--dport</span><span style="color:#D19A66;"> 80</span><span style="color:#7F848E;font-style:italic;">          # 目标端口</span></span>
<span class="line"><span style="color:#61AFEF;">--sport</span><span style="color:#98C379;"> 1024:65535</span><span style="color:#7F848E;font-style:italic;">  # 源端口范围</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 多端口匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> multiport</span><span style="color:#D19A66;"> --dports</span><span style="color:#98C379;"> 80,443,8080</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># IP 匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-s</span><span style="color:#98C379;"> 192.168.1.0/24</span><span style="color:#7F848E;font-style:italic;">   # 源地址</span></span>
<span class="line"><span style="color:#61AFEF;">-d</span><span style="color:#D19A66;"> 10.0.0.1</span><span style="color:#7F848E;font-style:italic;">          # 目标地址</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 接口匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-i</span><span style="color:#98C379;"> eth0</span><span style="color:#7F848E;font-style:italic;">              # 入接口</span></span>
<span class="line"><span style="color:#61AFEF;">-o</span><span style="color:#98C379;"> eth1</span><span style="color:#7F848E;font-style:italic;">              # 出接口</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 连接状态匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> conntrack</span><span style="color:#D19A66;"> --ctstate</span><span style="color:#98C379;"> NEW</span><span style="color:#7F848E;font-style:italic;">          # 新连接</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> conntrack</span><span style="color:#D19A66;"> --ctstate</span><span style="color:#98C379;"> ESTABLISHED</span><span style="color:#7F848E;font-style:italic;">  # 已建立</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> conntrack</span><span style="color:#D19A66;"> --ctstate</span><span style="color:#98C379;"> RELATED</span><span style="color:#7F848E;font-style:italic;">      # 相关（如 FTP 数据连接）</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> conntrack</span><span style="color:#D19A66;"> --ctstate</span><span style="color:#98C379;"> INVALID</span><span style="color:#7F848E;font-style:italic;">      # 无效</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 速率限制</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> limit</span><span style="color:#D19A66;"> --limit</span><span style="color:#98C379;"> 5/min</span><span style="color:#D19A66;"> --limit-burst</span><span style="color:#D19A66;"> 10</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># IP 范围匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> iprange</span><span style="color:#D19A66;"> --src-range</span><span style="color:#98C379;"> 192.168.1.100-192.168.1.200</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 字符串匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> string</span><span style="color:#D19A66;"> --string</span><span style="color:#98C379;"> &quot;example&quot;</span><span style="color:#D19A66;"> --algo</span><span style="color:#98C379;"> bm</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 时间匹配</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> time</span><span style="color:#D19A66;"> --timestart</span><span style="color:#98C379;"> 09:00</span><span style="color:#D19A66;"> --timestop</span><span style="color:#98C379;"> 18:00</span><span style="color:#D19A66;"> --weekdays</span><span style="color:#98C379;"> Mon,Fri</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 最近连接匹配（防暴力破解）</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> recent</span><span style="color:#D19A66;"> --set</span><span style="color:#D19A66;"> --name</span><span style="color:#98C379;"> ssh</span></span>
<span class="line"><span style="color:#61AFEF;">-m</span><span style="color:#98C379;"> recent</span><span style="color:#D19A66;"> --update</span><span style="color:#D19A66;"> --seconds</span><span style="color:#D19A66;"> 60</span><span style="color:#D19A66;"> --hitcount</span><span style="color:#D19A66;"> 5</span><span style="color:#D19A66;"> --name</span><span style="color:#98C379;"> ssh</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> DROP</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-iptables-持久化" tabindex="-1"><a class="header-anchor" href="#_3-5-iptables-持久化"><span>3.5 iptables 持久化</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 保存规则</span></span>
<span class="line"><span style="color:#61AFEF;">iptables-save</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/etc/iptables/rules.v4</span><span style="color:#7F848E;font-style:italic;">     # Debian/Ubuntu</span></span>
<span class="line"><span style="color:#61AFEF;">iptables-save</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/etc/sysconfig/iptables</span><span style="color:#7F848E;font-style:italic;">     # CentOS/RHEL</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 恢复规则</span></span>
<span class="line"><span style="color:#61AFEF;">iptables-restore</span><span style="color:#ABB2BF;"> &lt; </span><span style="color:#98C379;">/etc/iptables/rules.v4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 自动加载（Debian/Ubuntu 安装 iptables-persistent）</span></span>
<span class="line"><span style="color:#61AFEF;">apt</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> iptables-persistent</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># CentOS 7+ 使用 iptables-services</span></span>
<span class="line"><span style="color:#61AFEF;">yum</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> iptables-services</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> enable</span><span style="color:#98C379;"> iptables</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> save</span><span style="color:#98C379;"> iptables</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-firewalld" tabindex="-1"><a class="header-anchor" href="#_4-firewalld"><span>4. firewalld</span></a></h2><h3 id="_4-1-firewalld-设计哲学" tabindex="-1"><a class="header-anchor" href="#_4-1-firewalld-设计哲学"><span>4.1 firewalld 设计哲学</span></a></h3><p>firewalld 是 CentOS 7+/Fedora 的默认防火墙管理工具，相比 iptables 的核心改进：</p><table><thead><tr><th>特性</th><th>iptables</th><th>firewalld</th></tr></thead><tbody><tr><td>配置方式</td><td>命令行/脚本</td><td>命令行/XML/图形界面</td></tr><tr><td>运行时/永久</td><td>默认运行时</td><td>运行时与永久分离</td></tr><tr><td>规则组织</td><td>线性链</td><td>Zone 分区</td></tr><tr><td>修改生效</td><td>重建整条链</td><td>动态修改，不断连接</td></tr><tr><td>服务抽象</td><td>仅端口</td><td>预定义服务</td></tr><tr><td>复杂规则</td><td>需要写长命令</td><td>Rich Rule 语法</td></tr></tbody></table><h3 id="_4-2-zone-区域" tabindex="-1"><a class="header-anchor" href="#_4-2-zone-区域"><span>4.2 Zone 区域</span></a></h3><p>Zone 是 firewalld 的核心概念——不同的网络环境使用不同的安全策略：</p>`,17),i(d,{code:``}),o[4]||=n(`<p><strong>内置 Zone 说明：</strong></p><table><thead><tr><th>Zone</th><th>信任级别</th><th>说明</th></tr></thead><tbody><tr><td><code>drop</code></td><td>最低</td><td>丢弃所有入站包，仅允许出站</td></tr><tr><td><code>block</code></td><td>极低</td><td>拒绝所有入站包，返回 icmp-host-prohibited</td></tr><tr><td><code>public</code></td><td>低</td><td>公共网络，仅允许选定的入站连接</td></tr><tr><td><code>external</code></td><td>低</td><td>外部网络，出站走 NAT</td></tr><tr><td><code>dmz</code></td><td>中</td><td>DMZ 非军事区，仅允许选定入站</td></tr><tr><td><code>work</code></td><td>较高</td><td>工作网络，信任较多服务</td></tr><tr><td><code>home</code></td><td>高</td><td>家庭网络，基本信任</td></tr><tr><td><code>internal</code></td><td>高</td><td>内部网络，信任</td></tr><tr><td><code>trusted</code></td><td>最高</td><td>完全信任，允许所有连接</td></tr></tbody></table><h3 id="_4-3-firewalld-基本操作" tabindex="-1"><a class="header-anchor" href="#_4-3-firewalld-基本操作"><span>4.3 firewalld 基本操作</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看状态</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> status</span><span style="color:#98C379;"> firewalld</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --state</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看默认 zone</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --get-default-zone</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 设置默认 zone</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --set-default-zone=dmz</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有 zone</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --get-zones</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看活跃 zone</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --get-active-zones</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 zone 详情</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --zone=public</span><span style="color:#D19A66;"> --list-all</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有 zone 的永久配置</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --zone=public</span><span style="color:#D19A66;"> --list-all</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-service-与-port-管理" tabindex="-1"><a class="header-anchor" href="#_4-4-service-与-port-管理"><span>4.4 Service 与 Port 管理</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看可用服务</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --get-services</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加服务</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-service=http</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-service=https</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --zone=public</span><span style="color:#D19A66;"> --add-service=ssh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久添加服务</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --add-service=http</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --reload</span><span style="color:#7F848E;font-style:italic;">    # 重新加载永久配置</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 添加端口</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-port=8080/tcp</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-port=5000-5100/udp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久添加端口</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --add-port=8080/tcp</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --reload</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 移除服务/端口</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --remove-service=http</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --remove-port=8080/tcp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看已开放的服务和端口</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --list-services</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --list-ports</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>自定义服务：</strong></p><div class="language-xml line-numbers-mode" data-highlighter="shiki" data-ext="xml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-xml"><span class="line"><span style="color:#7F848E;font-style:italic;">&lt;!-- /etc/firewalld/services/myapp.xml --&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;?</span><span style="color:#E06C75;">xml</span><span style="color:#D19A66;"> version</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;1.0&quot;</span><span style="color:#D19A66;"> encoding</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;utf-8&quot;</span><span style="color:#ABB2BF;">?&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;</span><span style="color:#E06C75;">service</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">  &lt;</span><span style="color:#E06C75;">short</span><span style="color:#ABB2BF;">&gt;MyApp&lt;/</span><span style="color:#E06C75;">short</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">  &lt;</span><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">&gt;My custom application service&lt;/</span><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">  &lt;</span><span style="color:#E06C75;">port</span><span style="color:#D19A66;"> protocol</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;tcp&quot;</span><span style="color:#D19A66;"> port</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;8080&quot;</span><span style="color:#ABB2BF;">/&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">  &lt;</span><span style="color:#E06C75;">port</span><span style="color:#D19A66;"> protocol</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;tcp&quot;</span><span style="color:#D19A66;"> port</span><span style="color:#ABB2BF;">=</span><span style="color:#98C379;">&quot;8443&quot;</span><span style="color:#ABB2BF;">/&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">&lt;/</span><span style="color:#E06C75;">service</span><span style="color:#ABB2BF;">&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 加载自定义服务</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --reload</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-service=myapp</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-5-rich-rule-高级规则" tabindex="-1"><a class="header-anchor" href="#_4-5-rich-rule-高级规则"><span>4.5 Rich Rule 高级规则</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 允许特定 IP 访问 SSH</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; source address=&quot;192.168.1.0/24&quot; service name=&quot;ssh&quot; accept&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 拒绝特定 IP 段访问 80 端口</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; source address=&quot;10.0.0.0/8&quot; port port=&quot;80&quot; protocol=&quot;tcp&quot; reject&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 限制连接速率（防 SSH 暴力破解）</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule service name=&quot;ssh&quot; limit value=&quot;5/min&quot; accept&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 端口转发（本机 80 -&gt; 8080）</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; forward-port port=&quot;80&quot; protocol=&quot;tcp&quot; to-port=&quot;8080&quot;&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 跨机端口转发（80 -&gt; 192.168.2.100:8080）</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; forward-port port=&quot;80&quot; protocol=&quot;tcp&quot; to-addr=&quot;192.168.2.100&quot; to-port=&quot;8080&quot;&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 日志记录拒绝的连接</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; source address=&quot;192.168.1.0/24&quot; service name=&quot;ssh&quot; log prefix=&quot;ssh_deny&quot; level=&quot;notice&quot; reject&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久添加 rich rule</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;...&#39;</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --reload</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有 rich rule</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --list-rich-rules</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除 rich rule</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --remove-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; source address=&quot;192.168.1.0/24&quot; service name=&quot;ssh&quot; accept&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-6-接口与源地址绑定" tabindex="-1"><a class="header-anchor" href="#_4-6-接口与源地址绑定"><span>4.6 接口与源地址绑定</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 将接口绑定到 zone</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --zone=public</span><span style="color:#D19A66;"> --change-interface=enp3s0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 将源地址绑定到 zone</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --zone=trusted</span><span style="color:#D19A66;"> --add-source=192.168.1.0/24</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久绑定</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --zone=public</span><span style="color:#D19A66;"> --change-interface=enp3s0</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --zone=trusted</span><span style="color:#D19A66;"> --add-source=192.168.1.0/24</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 解绑</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --zone=trusted</span><span style="color:#D19A66;"> --remove-source=192.168.1.0/24</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --zone=public</span><span style="color:#D19A66;"> --remove-interface=enp3s0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-ufw-uncomplicated-firewall" tabindex="-1"><a class="header-anchor" href="#_5-ufw-uncomplicated-firewall"><span>5. UFW（Uncomplicated Firewall）</span></a></h2><p>UFW 是 Ubuntu 默认的防火墙前端，语法极其简洁：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 启用/禁用</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> enable</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> disable</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看状态</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> status</span><span style="color:#98C379;"> verbose</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 默认策略</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> default</span><span style="color:#98C379;"> deny</span><span style="color:#98C379;"> incoming</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> default</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> outgoing</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许服务</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> ssh</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> http</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> https</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> 8080/tcp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许特定 IP</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> from</span><span style="color:#98C379;"> 192.168.1.0/24</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> from</span><span style="color:#D19A66;"> 192.168.1.100</span><span style="color:#98C379;"> to</span><span style="color:#98C379;"> any</span><span style="color:#98C379;"> port</span><span style="color:#D19A66;"> 22</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 拒绝规则</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> deny</span><span style="color:#98C379;"> from</span><span style="color:#D19A66;"> 10.0.0.1</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> deny</span><span style="color:#98C379;"> 3306/tcp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 限速（防暴力破解）</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> limit</span><span style="color:#98C379;"> ssh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除规则</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> delete</span><span style="color:#98C379;"> allow</span><span style="color:#98C379;"> 8080/tcp</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> delete</span><span style="color:#D19A66;"> 3</span><span style="color:#7F848E;font-style:italic;">    # 按编号删除</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看编号</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> status</span><span style="color:#98C379;"> numbered</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 重置所有规则</span></span>
<span class="line"><span style="color:#61AFEF;">ufw</span><span style="color:#98C379;"> reset</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">UFW vs firewalld 选型</p><ul><li><strong>Ubuntu 系列</strong>：UFW 是原生选择，语法简洁</li><li><strong>CentOS/RHEL 系列</strong>：firewalld 是默认选择，Zone 机制更灵活</li><li><strong>需要精细控制</strong>：直接使用 iptables/nftables</li><li>三者底层都是 Netfilter，功能本质相同，区别在于管理便捷度</li></ul></div><h2 id="_6-nat-与端口转发" tabindex="-1"><a class="header-anchor" href="#_6-nat-与端口转发"><span>6. NAT 与端口转发</span></a></h2><h3 id="_6-1-nat-类型" tabindex="-1"><a class="header-anchor" href="#_6-1-nat-类型"><span>6.1 NAT 类型</span></a></h3>`,19),i(d,{code:``}),o[5]||=n(`<h3 id="_6-2-iptables-实现-nat" tabindex="-1"><a class="header-anchor" href="#_6-2-iptables-实现-nat"><span>6.2 iptables 实现 NAT</span></a></h3><p><strong>SNAT（出网）：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 内网机器通过网关上网（固定公网IP）</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> POSTROUTING</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> 192.168.1.0/24</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> SNAT</span><span style="color:#D19A66;"> --to-source</span><span style="color:#D19A66;"> 203.0.113.1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># MASQUERADE（动态公网IP，如拨号上网）</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> POSTROUTING</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> ppp0</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> MASQUERADE</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 开启内核转发</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/proc/sys/net/ipv4/ip_forward</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 永久生效</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;net.ipv4.ip_forward = 1&quot;</span><span style="color:#ABB2BF;"> &gt;&gt; </span><span style="color:#98C379;">/etc/sysctl.conf</span></span>
<span class="line"><span style="color:#61AFEF;">sysctl</span><span style="color:#D19A66;"> -p</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>DNAT（端口转发）：</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 将外部 80 端口转发到内网 192.168.1.100:8080</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> PREROUTING</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 80</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> DNAT</span><span style="color:#D19A66;"> --to-destination</span><span style="color:#98C379;"> 192.168.1.100:8080</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 本地端口转发（80 -&gt; 8080）</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> PREROUTING</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 80</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> REDIRECT</span><span style="color:#D19A66;"> --to-port</span><span style="color:#D19A66;"> 8080</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 指定入接口的端口转发</span></span>
<span class="line"><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> PREROUTING</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> tcp</span><span style="color:#D19A66;"> --dport</span><span style="color:#D19A66;"> 3389</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> DNAT</span><span style="color:#D19A66;"> --to</span><span style="color:#98C379;"> 192.168.1.50:3389</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">NAT 与回环问题</p><p>当内网机器通过公网 IP 访问 DNAT 服务时，数据包可能无法正确回传。解决方案：</p><ol><li>内网使用内部域名解析到内网 IP（DNS 分流）</li><li>使用 <code>SNAT + DNAT</code> 组合（Hairpin NAT）</li><li>在网关上同时做 SNAT，让回包经过网关</li></ol></div><h3 id="_6-3-firewalld-实现-nat" tabindex="-1"><a class="header-anchor" href="#_6-3-firewalld-实现-nat"><span>6.3 firewalld 实现 NAT</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 开启 masquerade（SNAT）</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-masquerade</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --add-masquerade</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 端口转发</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-forward-port=port=80:proto=tcp:toport=8080:toaddr=192.168.1.100</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --permanent</span><span style="color:#D19A66;"> --add-forward-port=port=80:proto=tcp:toport=8080:toaddr=192.168.1.100</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Rich Rule 端口转发</span></span>
<span class="line"><span style="color:#61AFEF;">firewall-cmd</span><span style="color:#D19A66;"> --add-rich-rule=</span><span style="color:#98C379;">&#39;rule family=&quot;ipv4&quot; forward-port port=&quot;80&quot; protocol=&quot;tcp&quot; to-addr=&quot;192.168.1.100&quot; to-port=&quot;8080&quot;&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_7-网络诊断工具" tabindex="-1"><a class="header-anchor" href="#_7-网络诊断工具"><span>7. 网络诊断工具</span></a></h2><h3 id="_7-1-网络诊断方法论" tabindex="-1"><a class="header-anchor" href="#_7-1-网络诊断方法论"><span>7.1 网络诊断方法论</span></a></h3>`,10),i(d,{code:``}),o[6]||=n(`<h3 id="_7-2-ss-替代-netstat" tabindex="-1"><a class="header-anchor" href="#_7-2-ss-替代-netstat"><span>7.2 ss -- 替代 netstat</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 查看所有 TCP 连接</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -t</span><span style="color:#7F848E;font-style:italic;">    # TCP</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -u</span><span style="color:#7F848E;font-style:italic;">    # UDP</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -l</span><span style="color:#7F848E;font-style:italic;">    # 监听状态</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -n</span><span style="color:#7F848E;font-style:italic;">    # 不解析域名</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -p</span><span style="color:#7F848E;font-style:italic;">    # 显示进程信息</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 常用组合</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tlnp</span><span style="color:#7F848E;font-style:italic;">             # 所有 TCP 监听端口及进程</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tlnp</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> :80</span><span style="color:#7F848E;font-style:italic;">  # 查找 80 端口监听</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -s</span><span style="color:#7F848E;font-style:italic;">                # 连接统计摘要</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看已建立的连接</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tn</span><span style="color:#98C379;"> state</span><span style="color:#98C379;"> established</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看特定状态的连接</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tn</span><span style="color:#98C379;"> state</span><span style="color:#98C379;"> time-wait</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tn</span><span style="color:#98C379;"> state</span><span style="color:#98C379;"> close-wait</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 按网段过滤</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tn</span><span style="color:#98C379;"> dst</span><span style="color:#98C379;"> 192.168.1.0/24</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看 socket 内存使用</span></span>
<span class="line"><span style="color:#61AFEF;">ss</span><span style="color:#D19A66;"> -tm</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">ss vs netstat</p><p><code>ss</code> 比 <code>netstat</code> 快得多——<code>ss</code> 直接读取内核 socket 表，而 <code>netstat</code> 遍历 <code>/proc/net/</code>。在连接数上万的服务器上，<code>netstat</code> 可能卡住，<code>ss</code> 则瞬间返回。</p></div><h3 id="_7-3-ping-与-traceroute" tabindex="-1"><a class="header-anchor" href="#_7-3-ping-与-traceroute"><span>7.3 ping 与 traceroute</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基本 ping</span></span>
<span class="line"><span style="color:#61AFEF;">ping</span><span style="color:#D19A66;"> 8.8.8.8</span></span>
<span class="line"><span style="color:#61AFEF;">ping</span><span style="color:#D19A66;"> -c</span><span style="color:#D19A66;"> 4</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">          # 发 4 个包后停止</span></span>
<span class="line"><span style="color:#61AFEF;">ping</span><span style="color:#D19A66;"> -i</span><span style="color:#D19A66;"> 0.5</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">        # 间隔 0.5 秒</span></span>
<span class="line"><span style="color:#61AFEF;">ping</span><span style="color:#D19A66;"> -s</span><span style="color:#D19A66;"> 1472</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">       # 指定包大小（测试 MTU）</span></span>
<span class="line"><span style="color:#61AFEF;">ping</span><span style="color:#D19A66;"> -W</span><span style="color:#D19A66;"> 2</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">          # 超时 2 秒</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># traceroute 跟踪路由</span></span>
<span class="line"><span style="color:#61AFEF;">traceroute</span><span style="color:#D19A66;"> 8.8.8.8</span></span>
<span class="line"><span style="color:#61AFEF;">traceroute</span><span style="color:#D19A66;"> -n</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">      # 不解析域名</span></span>
<span class="line"><span style="color:#61AFEF;">traceroute</span><span style="color:#D19A66;"> -T</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 80</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">  # TCP 80 端口（绕过 ICMP 限制）</span></span>
<span class="line"><span style="color:#61AFEF;">mtr</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">                # 持续跟踪（mtr = ping + traceroute）</span></span>
<span class="line"><span style="color:#61AFEF;">mtr</span><span style="color:#D19A66;"> -n</span><span style="color:#D19A66;"> --report</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">   # 报告模式</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-dns-诊断" tabindex="-1"><a class="header-anchor" href="#_7-4-dns-诊断"><span>7.4 DNS 诊断</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># nslookup 简单查询</span></span>
<span class="line"><span style="color:#61AFEF;">nslookup</span><span style="color:#98C379;"> www.example.com</span></span>
<span class="line"><span style="color:#61AFEF;">nslookup</span><span style="color:#98C379;"> www.example.com</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">  # 指定 DNS 服务器</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># dig 详细查询</span></span>
<span class="line"><span style="color:#61AFEF;">dig</span><span style="color:#98C379;"> www.example.com</span></span>
<span class="line"><span style="color:#61AFEF;">dig</span><span style="color:#98C379;"> www.example.com</span><span style="color:#98C379;"> +short</span><span style="color:#7F848E;font-style:italic;">         # 仅显示 IP</span></span>
<span class="line"><span style="color:#61AFEF;">dig</span><span style="color:#98C379;"> www.example.com</span><span style="color:#98C379;"> +trace</span><span style="color:#7F848E;font-style:italic;">         # 跟踪完整解析路径</span></span>
<span class="line"><span style="color:#61AFEF;">dig</span><span style="color:#98C379;"> www.example.com</span><span style="color:#98C379;"> MX</span><span style="color:#7F848E;font-style:italic;">             # 查询 MX 记录</span></span>
<span class="line"><span style="color:#61AFEF;">dig</span><span style="color:#D19A66;"> -x</span><span style="color:#D19A66;"> 8.8.8.8</span><span style="color:#7F848E;font-style:italic;">                     # 反向解析</span></span>
<span class="line"><span style="color:#61AFEF;">dig</span><span style="color:#98C379;"> www.example.com</span><span style="color:#98C379;"> @8.8.8.8</span><span style="color:#7F848E;font-style:italic;">       # 指定 DNS 服务器</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># host 简洁查询</span></span>
<span class="line"><span style="color:#61AFEF;">host</span><span style="color:#98C379;"> www.example.com</span></span>
<span class="line"><span style="color:#61AFEF;">host</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> MX</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"><span style="color:#61AFEF;">host</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> NS</span><span style="color:#98C379;"> example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-5-tcpdump-数据包抓取" tabindex="-1"><a class="header-anchor" href="#_7-5-tcpdump-数据包抓取"><span>7.5 tcpdump 数据包抓取</span></a></h3><p>tcpdump 是网络排障的终极武器，直接捕获网络接口上的数据包：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基本抓包</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#7F848E;font-style:italic;">                     # 抓取 eth0 上所有包</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -c</span><span style="color:#D19A66;"> 100</span><span style="color:#7F848E;font-style:italic;">              # 只抓 100 个包</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -w</span><span style="color:#98C379;"> capture.pcap</span><span style="color:#7F848E;font-style:italic;">     # 保存到文件（可用 Wireshark 分析）</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -r</span><span style="color:#98C379;"> capture.pcap</span><span style="color:#7F848E;font-style:italic;">             # 读取抓包文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 主机过滤</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> host</span><span style="color:#D19A66;"> 192.168.1.1</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> src</span><span style="color:#98C379;"> host</span><span style="color:#D19A66;"> 192.168.1.1</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> dst</span><span style="color:#98C379;"> host</span><span style="color:#D19A66;"> 192.168.1.1</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 端口过滤</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> port</span><span style="color:#D19A66;"> 80</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> src</span><span style="color:#98C379;"> port</span><span style="color:#D19A66;"> 80</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 协议过滤</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> tcp</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> udp</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> icmp</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 组合过滤</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> &#39;tcp and port 80 and host 192.168.1.1&#39;</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> &#39;tcp[tcpflags] &amp; (tcp-syn) != 0&#39;</span><span style="color:#7F848E;font-style:italic;">    # 仅 SYN 包</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#98C379;"> &#39;tcp[tcpflags] &amp; (tcp-rst) != 0&#39;</span><span style="color:#7F848E;font-style:italic;">    # 仅 RST 包</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 显示选项</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -nn</span><span style="color:#7F848E;font-style:italic;">        # 不解析域名和端口名</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -vv</span><span style="color:#7F848E;font-style:italic;">        # 详细输出</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -XX</span><span style="color:#7F848E;font-style:italic;">        # 显示包内容（十六进制+ASCII）</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -A</span><span style="color:#7F848E;font-style:italic;">         # ASCII 显示</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">tcpdump 在生产环境的使用</p><ol><li><strong>加 <code>-c</code> 限制包数量</strong>，避免磁盘写满</li><li><strong>加 <code>-s 0</code> 或 <code>-s 65535</code></strong> 抓取完整包（默认只抓 68 字节）</li><li><strong>用 <code>-w</code> 保存 pcap 文件</strong>，然后用 Wireshark 分析</li><li><strong>注意性能影响</strong>：高流量时 tcpdump 会消耗 CPU 和磁盘</li><li><strong>敏感信息</strong>：抓包内容可能包含密码，注意合规</li></ol></div><h2 id="_8-ssh-配置与安全加固" tabindex="-1"><a class="header-anchor" href="#_8-ssh-配置与安全加固"><span>8. SSH 配置与安全加固</span></a></h2><h3 id="_8-1-ssh-服务端配置" tabindex="-1"><a class="header-anchor" href="#_8-1-ssh-服务端配置"><span>8.1 SSH 服务端配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/ssh/sshd_config 关键配置</span></span>
<span class="line"><span style="color:#61AFEF;">Port</span><span style="color:#D19A66;"> 22</span><span style="color:#7F848E;font-style:italic;">                           # 监听端口（建议改为非标准端口）</span></span>
<span class="line"><span style="color:#61AFEF;">ListenAddress</span><span style="color:#D19A66;"> 0.0.0.0</span><span style="color:#7F848E;font-style:italic;">             # 监听地址</span></span>
<span class="line"><span style="color:#61AFEF;">Protocol</span><span style="color:#D19A66;"> 2</span><span style="color:#7F848E;font-style:italic;">                        # 仅使用 SSH 协议版本 2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 认证配置</span></span>
<span class="line"><span style="color:#61AFEF;">PermitRootLogin</span><span style="color:#98C379;"> no</span><span style="color:#7F848E;font-style:italic;">                # 禁止 root 直接登录</span></span>
<span class="line"><span style="color:#61AFEF;">MaxAuthTries</span><span style="color:#D19A66;"> 3</span><span style="color:#7F848E;font-style:italic;">                    # 最大认证尝试次数</span></span>
<span class="line"><span style="color:#61AFEF;">PubkeyAuthentication</span><span style="color:#98C379;"> yes</span><span style="color:#7F848E;font-style:italic;">          # 启用公钥认证</span></span>
<span class="line"><span style="color:#61AFEF;">PasswordAuthentication</span><span style="color:#98C379;"> no</span><span style="color:#7F848E;font-style:italic;">         # 禁用密码认证</span></span>
<span class="line"><span style="color:#61AFEF;">PermitEmptyPasswords</span><span style="color:#98C379;"> no</span><span style="color:#7F848E;font-style:italic;">           # 禁止空密码</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 会话配置</span></span>
<span class="line"><span style="color:#61AFEF;">LoginGraceTime</span><span style="color:#D19A66;"> 60</span><span style="color:#7F848E;font-style:italic;">                 # 登录超时</span></span>
<span class="line"><span style="color:#61AFEF;">ClientAliveInterval</span><span style="color:#D19A66;"> 300</span><span style="color:#7F848E;font-style:italic;">           # 空闲检测间隔（秒）</span></span>
<span class="line"><span style="color:#61AFEF;">ClientAliveCountMax</span><span style="color:#D19A66;"> 2</span><span style="color:#7F848E;font-style:italic;">             # 空闲检测次数</span></span>
<span class="line"><span style="color:#61AFEF;">MaxSessions</span><span style="color:#D19A66;"> 10</span><span style="color:#7F848E;font-style:italic;">                    # 最大会话数</span></span>
<span class="line"><span style="color:#61AFEF;">MaxStartups</span><span style="color:#98C379;"> 10:30:100</span><span style="color:#7F848E;font-style:italic;">            # 未认证连接限制</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 安全加固</span></span>
<span class="line"><span style="color:#61AFEF;">AllowUsers</span><span style="color:#98C379;"> admin</span><span style="color:#98C379;"> deploy@10.0.0.0/8</span><span style="color:#7F848E;font-style:italic;">   # 仅允许指定用户</span></span>
<span class="line"><span style="color:#61AFEF;">AllowGroups</span><span style="color:#98C379;"> sshusers</span><span style="color:#7F848E;font-style:italic;">               # 仅允许指定组</span></span>
<span class="line"><span style="color:#61AFEF;">X11Forwarding</span><span style="color:#98C379;"> no</span><span style="color:#7F848E;font-style:italic;">                   # 禁用 X11 转发</span></span>
<span class="line"><span style="color:#61AFEF;">AllowTcpForwarding</span><span style="color:#98C379;"> no</span><span style="color:#7F848E;font-style:italic;">              # 禁用 TCP 转发</span></span>
<span class="line"><span style="color:#61AFEF;">AllowAgentForwarding</span><span style="color:#98C379;"> no</span><span style="color:#7F848E;font-style:italic;">            # 禁用 Agent 转发</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 日志</span></span>
<span class="line"><span style="color:#61AFEF;">SyslogFacility</span><span style="color:#98C379;"> AUTH</span></span>
<span class="line"><span style="color:#61AFEF;">LogLevel</span><span style="color:#98C379;"> VERBOSE</span><span style="color:#7F848E;font-style:italic;">                   # 详细日志</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-2-ssh-密钥管理" tabindex="-1"><a class="header-anchor" href="#_8-2-ssh-密钥管理"><span>8.2 SSH 密钥管理</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 生成密钥对</span></span>
<span class="line"><span style="color:#61AFEF;">ssh-keygen</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> ed25519</span><span style="color:#D19A66;"> -C</span><span style="color:#98C379;"> &quot;admin@example.com&quot;</span><span style="color:#7F848E;font-style:italic;">       # 推荐：Ed25519</span></span>
<span class="line"><span style="color:#61AFEF;">ssh-keygen</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> rsa</span><span style="color:#D19A66;"> -b</span><span style="color:#D19A66;"> 4096</span><span style="color:#D19A66;"> -C</span><span style="color:#98C379;"> &quot;admin@example.com&quot;</span><span style="color:#7F848E;font-style:italic;">   # RSA 4096</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 分发公钥到远程主机</span></span>
<span class="line"><span style="color:#61AFEF;">ssh-copy-id</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> ~/.ssh/id_ed25519.pub</span><span style="color:#98C379;"> user@remote</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 手动添加公钥</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> ~/.ssh/id_ed25519.pub</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">ssh</span><span style="color:#98C379;"> user@remote</span><span style="color:#98C379;"> &#39;mkdir -p ~/.ssh &amp;&amp; cat &gt;&gt; ~/.ssh/authorized_keys&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 权限设置（非常重要！）</span></span>
<span class="line"><span style="color:#61AFEF;">chmod</span><span style="color:#D19A66;"> 700</span><span style="color:#98C379;"> ~/.ssh</span></span>
<span class="line"><span style="color:#61AFEF;">chmod</span><span style="color:#D19A66;"> 600</span><span style="color:#98C379;"> ~/.ssh/authorized_keys</span></span>
<span class="line"><span style="color:#61AFEF;">chmod</span><span style="color:#D19A66;"> 600</span><span style="color:#98C379;"> ~/.ssh/id_ed25519</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-3-ssh-客户端配置" tabindex="-1"><a class="header-anchor" href="#_8-3-ssh-客户端配置"><span>8.3 SSH 客户端配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># ~/.ssh/config</span></span>
<span class="line"><span style="color:#61AFEF;">Host</span><span style="color:#98C379;"> web</span></span>
<span class="line"><span style="color:#61AFEF;">    HostName</span><span style="color:#D19A66;"> 192.168.1.100</span></span>
<span class="line"><span style="color:#61AFEF;">    Port</span><span style="color:#D19A66;"> 2222</span></span>
<span class="line"><span style="color:#61AFEF;">    User</span><span style="color:#98C379;"> admin</span></span>
<span class="line"><span style="color:#61AFEF;">    IdentityFile</span><span style="color:#98C379;"> ~/.ssh/id_web</span></span>
<span class="line"><span style="color:#61AFEF;">    ForwardAgent</span><span style="color:#98C379;"> no</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">Host</span><span style="color:#98C379;"> db-</span><span style="color:#E5C07B;">*</span></span>
<span class="line"><span style="color:#61AFEF;">    User</span><span style="color:#98C379;"> dbadmin</span></span>
<span class="line"><span style="color:#61AFEF;">    IdentityFile</span><span style="color:#98C379;"> ~/.ssh/id_db</span></span>
<span class="line"><span style="color:#61AFEF;">    ProxyJump</span><span style="color:#98C379;"> web</span><span style="color:#7F848E;font-style:italic;">                # 跳板机</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">Host</span><span style="color:#E5C07B;"> *</span></span>
<span class="line"><span style="color:#61AFEF;">    ServerAliveInterval</span><span style="color:#D19A66;"> 60</span></span>
<span class="line"><span style="color:#61AFEF;">    ServerAliveCountMax</span><span style="color:#D19A66;"> 3</span></span>
<span class="line"><span style="color:#61AFEF;">    StrictHostKeyChecking</span><span style="color:#98C379;"> accept-new</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-4-ssh-安全加固清单" tabindex="-1"><a class="header-anchor" href="#_8-4-ssh-安全加固清单"><span>8.4 SSH 安全加固清单</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 安装 fail2ban 防暴力破解</span></span>
<span class="line"><span style="color:#61AFEF;">apt</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> fail2ban</span><span style="color:#7F848E;font-style:italic;">       # Debian/Ubuntu</span></span>
<span class="line"><span style="color:#61AFEF;">yum</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> fail2ban</span><span style="color:#7F848E;font-style:italic;">       # CentOS</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /etc/fail2ban/jail.local</span></span>
<span class="line"><span style="color:#ABB2BF;">[sshd]</span></span>
<span class="line"><span style="color:#61AFEF;">enabled</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> true</span></span>
<span class="line"><span style="color:#61AFEF;">port</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 22</span></span>
<span class="line"><span style="color:#61AFEF;">filter</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> sshd</span></span>
<span class="line"><span style="color:#61AFEF;">logpath</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> /var/log/auth.log</span></span>
<span class="line"><span style="color:#61AFEF;">maxretry</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 3</span></span>
<span class="line"><span style="color:#61AFEF;">findtime</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 600</span></span>
<span class="line"><span style="color:#61AFEF;">bantime</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 3600</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> enable</span><span style="color:#D19A66;"> --now</span><span style="color:#98C379;"> fail2ban</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 检查配置语法</span></span>
<span class="line"><span style="color:#61AFEF;">sshd</span><span style="color:#D19A66;"> -t</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 重启 sshd（注意保持当前连接！）</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> reload</span><span style="color:#98C379;"> sshd</span><span style="color:#7F848E;font-style:italic;">    # 优雅重载，不断开现有连接</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">SSH 加锁步骤</p><p>修改 sshd_config 后，<strong>千万不要直接关闭当前 SSH 会话</strong>！正确步骤：</p><ol><li>在当前会话中修改配置</li><li><code>sshd -t</code> 检查语法</li><li><code>systemctl reload sshd</code> 重载</li><li><strong>新开一个终端</strong>测试能否登录</li><li>确认新连接正常后，才能关闭旧会话</li></ol></div><h2 id="_9-vpn-基础" tabindex="-1"><a class="header-anchor" href="#_9-vpn-基础"><span>9. VPN 基础</span></a></h2><h3 id="_9-1-常见-vpn-技术对比" tabindex="-1"><a class="header-anchor" href="#_9-1-常见-vpn-技术对比"><span>9.1 常见 VPN 技术对比</span></a></h3><table><thead><tr><th>VPN 类型</th><th>协议</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>WireGuard</strong></td><td>UDP</td><td>现代、极简、高性能</td><td>点对点、移动端</td></tr><tr><td><strong>OpenVPN</strong></td><td>UDP/TCP</td><td>成熟稳定、灵活</td><td>企业远程接入</td></tr><tr><td><strong>IPsec</strong></td><td>ESP/IKE</td><td>内核级、标准协议</td><td>站点到站点</td></tr><tr><td><strong>OpenConnect</strong></td><td>TLS</td><td>Cisco AnyConnect 兼容</td><td>兼容旧设备</td></tr></tbody></table><h3 id="_9-2-wireguard-快速配置" tabindex="-1"><a class="header-anchor" href="#_9-2-wireguard-快速配置"><span>9.2 WireGuard 快速配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 安装</span></span>
<span class="line"><span style="color:#61AFEF;">apt</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> wireguard</span><span style="color:#7F848E;font-style:italic;">     # Debian/Ubuntu</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 生成密钥对</span></span>
<span class="line"><span style="color:#61AFEF;">wg</span><span style="color:#98C379;"> genkey</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tee</span><span style="color:#98C379;"> privatekey</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">wg</span><span style="color:#98C379;"> pubkey</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">publickey</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 服务器配置 /etc/wireguard/wg0.conf</span></span>
<span class="line"><span style="color:#ABB2BF;">[Interface]</span></span>
<span class="line"><span style="color:#61AFEF;">PrivateKey</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">服务器私</span><span style="color:#ABB2BF;">钥&gt;</span></span>
<span class="line"><span style="color:#61AFEF;">Address</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> 10.0.0.1/24</span></span>
<span class="line"><span style="color:#61AFEF;">ListenPort</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 51820</span></span>
<span class="line"><span style="color:#61AFEF;">PostUp</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> iptables</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> FORWARD</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> wg0</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span><span style="color:#ABB2BF;">; </span><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -A</span><span style="color:#98C379;"> POSTROUTING</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> MASQUERADE</span></span>
<span class="line"><span style="color:#61AFEF;">PostDown</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> iptables</span><span style="color:#D19A66;"> -D</span><span style="color:#98C379;"> FORWARD</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> wg0</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> ACCEPT</span><span style="color:#ABB2BF;">; </span><span style="color:#61AFEF;">iptables</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> nat</span><span style="color:#D19A66;"> -D</span><span style="color:#98C379;"> POSTROUTING</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -j</span><span style="color:#98C379;"> MASQUERADE</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[Peer]</span></span>
<span class="line"><span style="color:#61AFEF;">PublicKey</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">客户端公</span><span style="color:#ABB2BF;">钥&gt;</span></span>
<span class="line"><span style="color:#61AFEF;">AllowedIPs</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> 10.0.0.2/32</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 客户端配置</span></span>
<span class="line"><span style="color:#ABB2BF;">[Interface]</span></span>
<span class="line"><span style="color:#61AFEF;">PrivateKey</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">客户端私</span><span style="color:#ABB2BF;">钥&gt;</span></span>
<span class="line"><span style="color:#61AFEF;">Address</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> 10.0.0.2/24</span></span>
<span class="line"><span style="color:#61AFEF;">DNS</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 8.8.8.8</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[Peer]</span></span>
<span class="line"><span style="color:#61AFEF;">PublicKey</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">服务器公</span><span style="color:#ABB2BF;">钥&gt;</span></span>
<span class="line"><span style="color:#61AFEF;">Endpoint</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">服务器公网I</span><span style="color:#ABB2BF;">P&gt;</span><span style="color:#98C379;">:51820</span></span>
<span class="line"><span style="color:#61AFEF;">AllowedIPs</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> 0.0.0.0/0</span></span>
<span class="line"><span style="color:#61AFEF;">PersistentKeepalive</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 25</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 启动</span></span>
<span class="line"><span style="color:#61AFEF;">wg-quick</span><span style="color:#98C379;"> up</span><span style="color:#98C379;"> wg0</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> enable</span><span style="color:#98C379;"> wg-quick@wg0</span></span>
<span class="line"><span style="color:#61AFEF;">wg</span><span style="color:#98C379;"> show</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-3-openvpn-快速配置" tabindex="-1"><a class="header-anchor" href="#_9-3-openvpn-快速配置"><span>9.3 OpenVPN 快速配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">apt</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> openvpn</span><span style="color:#98C379;"> easy-rsa</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 初始化 PKI</span></span>
<span class="line"><span style="color:#61AFEF;">make-cadir</span><span style="color:#98C379;"> /etc/openvpn/easy-rsa</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> /etc/openvpn/easy-rsa</span></span>
<span class="line"><span style="color:#61AFEF;">./easyrsa</span><span style="color:#98C379;"> init-pki</span></span>
<span class="line"><span style="color:#61AFEF;">./easyrsa</span><span style="color:#98C379;"> build-ca</span></span>
<span class="line"><span style="color:#61AFEF;">./easyrsa</span><span style="color:#98C379;"> gen-dh</span></span>
<span class="line"><span style="color:#61AFEF;">./easyrsa</span><span style="color:#98C379;"> build-server-full</span><span style="color:#98C379;"> server</span><span style="color:#98C379;"> nopass</span></span>
<span class="line"><span style="color:#61AFEF;">./easyrsa</span><span style="color:#98C379;"> build-client-full</span><span style="color:#98C379;"> client1</span><span style="color:#98C379;"> nopass</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 服务器配置 /etc/openvpn/server/server.conf</span></span>
<span class="line"><span style="color:#61AFEF;">port</span><span style="color:#D19A66;"> 1194</span></span>
<span class="line"><span style="color:#61AFEF;">proto</span><span style="color:#98C379;"> udp</span></span>
<span class="line"><span style="color:#61AFEF;">dev</span><span style="color:#98C379;"> tun</span></span>
<span class="line"><span style="color:#61AFEF;">ca</span><span style="color:#98C379;"> /etc/openvpn/easy-rsa/pki/ca.crt</span></span>
<span class="line"><span style="color:#61AFEF;">cert</span><span style="color:#98C379;"> /etc/openvpn/easy-rsa/pki/issued/server.crt</span></span>
<span class="line"><span style="color:#61AFEF;">key</span><span style="color:#98C379;"> /etc/openvpn/easy-rsa/pki/private/server.key</span></span>
<span class="line"><span style="color:#61AFEF;">dh</span><span style="color:#98C379;"> /etc/openvpn/easy-rsa/pki/dh.pem</span></span>
<span class="line"><span style="color:#61AFEF;">server</span><span style="color:#D19A66;"> 10.8.0.0</span><span style="color:#D19A66;"> 255.255.255.0</span></span>
<span class="line"><span style="color:#61AFEF;">push</span><span style="color:#98C379;"> &quot;redirect-gateway def1 bypass-dhcp&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">push</span><span style="color:#98C379;"> &quot;dhcp-option DNS 8.8.8.8&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">keepalive</span><span style="color:#D19A66;"> 10</span><span style="color:#D19A66;"> 120</span></span>
<span class="line"><span style="color:#61AFEF;">cipher</span><span style="color:#98C379;"> AES-256-GCM</span></span>
<span class="line"><span style="color:#61AFEF;">persist-key</span></span>
<span class="line"><span style="color:#61AFEF;">persist-tun</span></span>
<span class="line"><span style="color:#61AFEF;">verb</span><span style="color:#D19A66;"> 3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> enable</span><span style="color:#D19A66;"> --now</span><span style="color:#98C379;"> openvpn-server@server</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_10-实战-完整防火墙配置脚本" tabindex="-1"><a class="header-anchor" href="#_10-实战-完整防火墙配置脚本"><span>10. 实战：完整防火墙配置脚本</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;">#!/bin/bash</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ============================================================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 企业级 iptables 防火墙脚本</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 适用于：Web 服务器（HTTP/HTTPS + SSH + 监控）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ============================================================</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 变量定义</span></span>
<span class="line"><span style="color:#E06C75;">IPT</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;/sbin/iptables&quot;</span></span>
<span class="line"><span style="color:#E06C75;">ADMIN_NET</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;192.168.1.0/24&quot;</span></span>
<span class="line"><span style="color:#E06C75;">MONITOR_NET</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;10.0.0.0/24&quot;</span></span>
<span class="line"><span style="color:#E06C75;">SSH_PORT</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">2222</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 清空所有规则</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -F</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -X</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -Z</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -t nat -F</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -t mangle -F</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 默认策略：拒绝所有入站，允许所有出站</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -P INPUT DROP</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -P FORWARD DROP</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -P OUTPUT ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ====================== INPUT 链 ======================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 允许回环接口</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -i lo -j ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 允许已建立和相关连接</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 丢弃无效包</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -m conntrack --ctstate INVALID -j DROP</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. ICMP 限速</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -p icmp --icmp-type echo-request -m limit --limit 1/s --limit-burst 5 -j ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 5. SSH - 仅允许管理网段，防暴力破解</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -s </span><span style="color:#E06C75;">$ADMIN_NET</span><span style="color:#ABB2BF;"> -p tcp --dport </span><span style="color:#E06C75;">$SSH_PORT</span><span style="color:#ABB2BF;"> -m conntrack --ctstate NEW -m recent --set --name ssh</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -s </span><span style="color:#E06C75;">$ADMIN_NET</span><span style="color:#ABB2BF;"> -p tcp --dport </span><span style="color:#E06C75;">$SSH_PORT</span><span style="color:#ABB2BF;"> -m conntrack --ctstate NEW -m recent --update --seconds 60 --hitcount 5 --name ssh -j DROP</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -s </span><span style="color:#E06C75;">$ADMIN_NET</span><span style="color:#ABB2BF;"> -p tcp --dport </span><span style="color:#E06C75;">$SSH_PORT</span><span style="color:#ABB2BF;"> -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 6. HTTP/HTTPS - 允许所有</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -p tcp --dport 80 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -p tcp --dport 443 -m conntrack --ctstate NEW -j ACCEPT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 7. 监控端口 - 仅允许监控网段</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -s </span><span style="color:#E06C75;">$MONITOR_NET</span><span style="color:#ABB2BF;"> -p tcp --dport 9100 -m conntrack --ctstate NEW -j ACCEPT   </span><span style="color:#7F848E;font-style:italic;"># Node Exporter</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -s </span><span style="color:#E06C75;">$MONITOR_NET</span><span style="color:#ABB2BF;"> -p tcp --dport 9090 -m conntrack --ctstate NEW -j ACCEPT   </span><span style="color:#7F848E;font-style:italic;"># Prometheus</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 8. 记录被拒绝的连接</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -m limit --limit 5/min -j LOG --log-prefix </span><span style="color:#98C379;">&quot;iptables-deny: &quot;</span><span style="color:#ABB2BF;"> --log-level 4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 9. 最终拒绝</span></span>
<span class="line"><span style="color:#E06C75;">$IPT</span><span style="color:#ABB2BF;"> -A INPUT -j DROP</span></span>
<span class="line"></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;Firewall rules applied successfully.&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;SSH port: </span><span style="color:#E06C75;">$SSH_PORT</span><span style="color:#98C379;"> (from </span><span style="color:#E06C75;">$ADMIN_NET</span><span style="color:#98C379;"> only)&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;HTTP/HTTPS: open&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;Monitoring: from </span><span style="color:#E06C75;">$MONITOR_NET</span><span style="color:#98C379;"> only&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">防火墙配置核心原则</p><ol><li><strong>默认拒绝</strong>：<code>INPUT DROP</code>，仅放行必要服务</li><li><strong>状态检测</strong>：<code>ESTABLISHED,RELATED</code> 放首位，避免后续规则干扰</li><li><strong>最小权限</strong>：限制来源 IP，不开放 0.0.0.0/0</li><li><strong>防暴力破解</strong>：使用 <code>recent</code> 模块限速 SSH</li><li><strong>日志记录</strong>：对拒绝的包做日志，方便排查</li><li><strong>配置持久化</strong>：务必 <code>iptables-save</code> 或启用 firewalld 永久配置</li></ol></div><h2 id="_11-网络配置速查表" tabindex="-1"><a class="header-anchor" href="#_11-网络配置速查表"><span>11. 网络配置速查表</span></a></h2><table><thead><tr><th>功能</th><th>命令</th></tr></thead><tbody><tr><td>查看 IP</td><td><code>ip addr show</code></td></tr><tr><td>查看 MAC</td><td><code>ip link show</code></td></tr><tr><td>查看路由</td><td><code>ip route show</code></td></tr><tr><td>查看 ARP</td><td><code>ip neigh show</code></td></tr><tr><td>查看监听端口</td><td><code>ss -tlnp</code></td></tr><tr><td>查看连接状态</td><td><code>ss -tn state established</code></td></tr><tr><td>DNS 查询</td><td><code>dig +short example.com</code></td></tr><tr><td>跟踪路由</td><td><code>mtr -n example.com</code></td></tr><tr><td>抓包</td><td><code>tcpdump -i eth0 -w file.pcap</code></td></tr><tr><td>查看 iptables</td><td><code>iptables -L -n -v --line-numbers</code></td></tr><tr><td>查看 firewalld</td><td><code>firewall-cmd --list-all</code></td></tr><tr><td>查看网卡速率</td><td><code>ethtool eth0</code></td></tr><tr><td>查看连接追踪</td><td><code>conntrack -L</code></td></tr><tr><td>刷新 ARP 缓存</td><td><code>ip neigh flush all</code></td></tr><tr><td>刷新路由缓存</td><td><code>ip route flush cache</code></td></tr></tbody></table><h2 id="参考资源" tabindex="-1"><a class="header-anchor" href="#参考资源"><span>参考资源</span></a></h2><ul><li>《鸟哥的 Linux 私房菜——服务器架设篇》</li><li>《Linux 命令行与 Shell 脚本编程大全》</li><li><a href="https://www.netfilter.org/documentation/" target="_blank" rel="noopener noreferrer">iptables 官方文档</a></li><li><a href="https://firewalld.org/documentation/" target="_blank" rel="noopener noreferrer">firewalld 官方文档</a></li><li><a href="https://www.wireguard.com/" target="_blank" rel="noopener noreferrer">WireGuard 官方文档</a></li><li><a href="https://book.douban.com/subject/1088054/" target="_blank" rel="noopener noreferrer">TCP/IP 详解 卷1：协议</a></li></ul>`,35)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};